import sys


def main():
    N, P = map(int, sys.stdin.buffer.read().split())
    half = N // 2
    maxE = N * (N - 1) // 2

    # binomial coefficients
    C = [[0] * (N + 1) for _ in range(N + 1)]
    for n in range(N + 1):
        C[n][0] = C[n][n] = 1
        for k in range(1, n):
            C[n][k] = (C[n - 1][k - 1] + C[n - 1][k]) % P

    # binom_poly[t] = coefficients of (1+x)^t
    binom_poly = [[1]]
    for t in range(1, maxE + 1):
        prev = binom_poly[-1]
        cur = [1] * (t + 1)
        for k in range(1, t):
            cur[k] = (prev[k - 1] + prev[k]) % P
        cur[t] = 1
        binom_poly.append(cur)

    def conv(f, g):
        nf, ng = len(f), len(g)
        out = [0] * (nf + ng - 1)
        for i, fi in enumerate(f):
            if fi == 0:
                continue
            for j, gj in enumerate(g):
                if gj:
                    out[i + j] = (out[i + j] + fi * gj) % P
        return out

    # q[a][s] = ((1+x)^a - 1)^s * (1+x)^(s(s-1)/2)
    q = [[None] * (N + 1) for _ in range(N + 1)]
    for a in range(1, N + 1):
        base = binom_poly[a][:]
        base[0] = 0  # (1+x)^a - 1
        for s in range(1, N - a + 1):
            # base^s
            p = [1]
            for _ in range(s):
                p = conv(p, base)
            w = binom_poly[s * (s - 1) // 2]
            q[a][s] = conv(p, w)

    # state: (u, a, e, p) -> edge polynomial
    # u = used vertices, a = last layer size, e = even-side vertices,
    # p = parity of the NEXT layer to add (1 = odd)
    states = {(1, 1, 1, 1): [1]}

    for u in range(1, N):
        current = [(key, poly) for key, poly in states.items() if key[0] == u]
        for (uu, a, e, p), poly in current:
            rem = N - u
            for s in range(1, rem + 1):
                ne = e + s if p == 0 else e
                if ne > half:
                    continue
                np = 1 - p
                qpoly = q[a][s]
                out = conv(poly, qpoly)
                comb = C[rem][s]
                if comb != 1:
                    out = [v * comb % P for v in out]
                key = (u + s, s, ne, np)
                old = states.get(key)
                if old is None:
                    states[key] = out
                else:
                    if len(old) < len(out):
                        old += [0] * (len(out) - len(old))
                    for i, v in enumerate(out):
                        old[i] = (old[i] + v) % P

    result = [0] * (maxE + 1)
    for (u, a, e, p), poly in states.items():
        if u == N and e == half:
            for m, v in enumerate(poly):
                result[m] = (result[m] + v) % P

    print(" ".join(str(result[m]) for m in range(N - 1, maxE + 1)))


if __name__ == "__main__":
    main()

